<?php
require_once __DIR__ . '/app.php'; require_login(); $me=current_user(); $id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT p.id,p.user_id,p.image_path,p.caption,p.created_at,u.username,u.display_name,u.avatar_path,(SELECT COUNT(*) FROM likes WHERE post_id=p.id) like_count,EXISTS(SELECT 1 FROM likes WHERE post_id=p.id AND user_id=?) liked FROM posts p JOIN users u ON u.id=p.user_id WHERE p.id=?');$stmt->bind_param('ii',$me['id'],$id);$stmt->execute();$post=$stmt->get_result()->fetch_assoc();if(!$post){http_response_code(404);page_start('Post not found');echo '<main class="content-wrap"><div class="empty-state card"><h2>Post not found</h2><a href="feed.php">Back to feed</a></div></main>';page_end();exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$comment=trim((string)($_POST['comment']??''));if($comment!==''){if(mb_strlen($comment)>1000)flash('Comments must be 1,000 characters or fewer.','error');else{$stmt=$conn->prepare('INSERT INTO comments (post_id,user_id,body) VALUES (?,?,?)');$stmt->bind_param('iis',$id,$me['id'],$comment);$stmt->execute();flash('Comment added.');}}redirect('post.php?id='.$id);}
$stmt=$conn->prepare('SELECT c.body,c.created_at,u.username,u.display_name,u.avatar_path FROM comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=? ORDER BY c.created_at ASC');$stmt->bind_param('i',$id);$stmt->execute();$comments=$stmt->get_result();page_start('Post');
?>
<main class="content-wrap detail-layout"><article class="post-card card detail-post"><div class="post-header"><a class="author" href="profile.php?u=<?= urlencode($post['username']) ?>"><img class="avatar" src="<?= e(avatar(['avatar_path'=>$post['avatar_path']])) ?>" alt=""><span><strong><?= e($post['display_name']) ?></strong><small>@<?= e($post['username']) ?></small></span></a><time><?= e(date('M j · g:i a',strtotime($post['created_at']))) ?></time></div><img class="detail-image" src="<?= e($post['image_path']) ?>" alt="Post by <?= e($post['username']) ?>"><?php if($post['caption']!==''): ?><p class="post-caption"><?= nl2br(e($post['caption'])) ?></p><?php endif; ?><div class="post-actions"><form method="post" action="like.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><button class="action-button <?= $post['liked']?'liked':'' ?>" type="submit"><?= $post['liked']?'♥ Liked':'♡ Like' ?> <span><?= (int)$post['like_count'] ?></span></button></form></div></article><section class="comments-panel card"><span class="eyebrow muted">THE CONVERSATION</span><h2>Comments<span class="heading-dot">.</span></h2><form method="post" class="comment-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><textarea name="comment" rows="3" maxlength="1000" placeholder="Add something thoughtful…" required></textarea><button class="btn primary" type="submit">Comment →</button></form><?php if($comments->num_rows===0): ?><p class="muted no-comments">No comments yet. Start the conversation.</p><?php else: ?><?php while($c=$comments->fetch_assoc()): ?><div class="comment-item"><img class="avatar small-avatar" src="<?= e(avatar(['avatar_path'=>$c['avatar_path']])) ?>" alt=""><div><div class="comment-meta"><strong><?= e($c['display_name']) ?></strong><span>@<?= e($c['username']) ?></span></div><p><?= nl2br(e($c['body'])) ?></p><small><?= e(date('M j · g:i a',strtotime($c['created_at']))) ?></small></div></div><?php endwhile; ?><?php endif; ?></section></main>
<?php page_end(); ?>
